    throw new Error('sections must be an array');
  }

  const seenIds = new Set();
  const validated = new Array(sections.length);

  // Validate and frame every entry before making any packing decision.
  for (let index = 0; index < sections.length; index += 1) {
    if (!Object.hasOwn(sections, index)) {
      throw new Error(`sections must be dense (missing index ${index})`);
    }

    const section = sections[index];
    if (typeof section !== 'object' || section === null || Array.isArray(section)) {
      throw new Error(`section at index ${index} must be a non-null, non-array object`);
    }
    if (typeof section.id !== 'string' || section.id.length === 0) {
