      throw new Error(`section at index ${index} has an invalid priority`);
    }
    if (typeof section.required !== 'boolean') {
      throw new Error(`section at index ${index} has an invalid required flag`);
    }
    if (seenIds.has(section.id)) {
      throw new Error(`duplicate section id at index ${index}`);
    }
    seenIds.add(section.id);

    const frame = `### ${JSON.stringify(section.id)}\n${section.text}\n`;
