import {readFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {fileURLToPath} from 'node:url';

function isNonnegativeSafeInteger(value) {
  return Number.isSafeInteger(value) && value >= 0;
}

export function packContext(sections, maxBytes) {
  if (!isNonnegativeSafeInteger(maxBytes)) {
    throw new Error('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) {
    throw new Error('sections must be an array');
  }

  const seenIds = new Set();
  const validated = new Array(sections.length);

  // Validate and frame every entry before making any packing decision.
  for (let index = 0; index < sections.length; index += 1) {
    if (!Object.hasOwn(sections, index)) {
      throw new Error(`sections must be dense (missing index ${index})`);
    }

    const section = sections[index];
    if (typeof section !== 'object' || section === null || Array.isArray(section)) {
      throw new Error(`section at index ${index} must be a non-null, non-array object`);
    }
    const {id, text, priority, required} = section;
    if (typeof id !== 'string' || id.length === 0) {
      throw new Error(`section at index ${index} has an invalid id`);
    }
    if (typeof text !== 'string') {
      throw new Error(`section at index ${index} has invalid text`);
    }
    if (!isNonnegativeSafeInteger(priority)) {
      throw new Error(`section at index ${index} has an invalid priority`);
    }
    if (typeof required !== 'boolean') {
      throw new Error(`section at index ${index} has an invalid required flag`);
    }
    if (seenIds.has(id)) {
      throw new Error(`duplicate section id at index ${index}`);
    }
    seenIds.add(id);

    const frame = `### ${JSON.stringify(id)}\n${text}\n`;
    validated[index] = {
      id,
      priority,
      required,
      index,
      frame,
      bytes: Buffer.byteLength(frame, 'utf8'),
    };
  }

  const required = validated.filter((section) => section.required);
  const optional = validated.filter((section) => !section.required);
  const requiredBytes = required.reduce((total, section) => total + section.bytes, 0);

  if (requiredBytes > maxBytes) {
    throw new Error('required sections exceed maxBytes');
  }

  optional.sort((left, right) =>
    right.priority - left.priority || left.index - right.index,
  );

  const selected = [...required];
  const omittedIds = new Set();
  let bytes = requiredBytes;

  for (const section of optional) {
    if (section.bytes <= maxBytes - bytes) {
      selected.push(section);
      bytes += section.bytes;
    } else {
      omittedIds.add(section.id);
    }
  }

  return {
    text: selected.map((section) => section.frame).join(''),
    bytes,
    included: selected.map((section) => section.id),
    omitted: validated
      .filter((section) => omittedIds.has(section.id))
      .map((section) => section.id),
  };
}

function runCli() {
  try {
    if (process.argv.length !== 3) {
      throw new Error('expected exactly one INPUT_JSON_FILE argument');
    }

    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    if (typeof input !== 'object' || input === null || Array.isArray(input)) {
      throw new Error('input JSON must be an object');
    }

    const result = packContext(input.sections, input.maxBytes);
    process.stdout.write(`${JSON.stringify(result)}\n`);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`Error: ${message || 'unknown error'}\n`);
    process.exitCode = 2;
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  runCli();
}

